/* 
  T.I.T.A.N. — Tech & Ingot Transfer and Allocation Network
  Author: Backstabbath

  Usage Guide:
  1. Rename any assembler you want managed to include “[Autostock]” in its name.
  2. Paste this script into a Programmable Block and Compile & Save.
  3. Each tick (for non‐disassembly assemblers) it will:
     • Clear assembler outputs into cargo.
     • Remove any assembler-input items not needed by your queue.
     • Stock exactly the minimum prerequisites + 2× buffer:
         – Tech2x ← ingots
         – Tech4x ← 5×Tech2x → pulls 10
         – Tech8x ← 5×Tech4x → pulls 10
         – Tech16x ← 250×Tech8x → pulls 500
         – Tech32x ← 2×Tech16x → pulls 4
     • Restock ingots/gravel up to 800 on every 3rd full cycle.
     • Purge any excess ingots above 800.
  4. Assemblers in Disassembly mode are completely left alone.
*/

const string assemblerTag="[Autostock]";const int ingotTarget=800,ingotRestockDelay=3,transfersPerTick=10,bufferMultiplier=2;readonly string[] techTypeIds={"MyObjectBuilder_Component/Tech2x","MyObjectBuilder_Component/Tech4x","MyObjectBuilder_Component/Tech8x","MyObjectBuilder_Component/Tech16x","MyObjectBuilder_Component/Tech32x"};readonly int[] prereqRatios={0,5,5,250,2};readonly HashSet<string> ingotAndOreSet=new HashSet<string>{"MyObjectBuilder_Ingot/Iron","MyObjectBuilder_Ingot/Nickel","MyObjectBuilder_Ingot/Cobalt","MyObjectBuilder_Ingot/Magnesium","MyObjectBuilder_Ingot/Silicon","MyObjectBuilder_Ingot/Silver","MyObjectBuilder_Ingot/Gold","MyObjectBuilder_Ingot/Platinum","MyObjectBuilder_Ingot/Uranium","MyObjectBuilder_Ore/Gravel"};MyItemType[] techItemTypes;List<IMyAssembler> assemblers=new List<IMyAssembler>();List<IMyInventory> cargoInventories=new List<IMyInventory>();List<MyInventoryItem> sharedItemList=new List<MyInventoryItem>();Dictionary<string,List<CargoItemRef>> cargoMap=new Dictionary<string,List<CargoItemRef>>();List<TransferJob> transferQueue=new List<TransferJob>();int assemblerIndex=0,fullCycles=0;bool inputsCleared=false;public Program(){techItemTypes=new MyItemType[techTypeIds.Length];for(int i=0;i<techTypeIds.Length;i++){var p=techTypeIds[i].Split('/');techItemTypes[i]=new MyItemType(p[0],p[1]);}Runtime.UpdateFrequency=UpdateFrequency.Update1;}public void Main(string argument,UpdateType updateSource){ProcessTransferQueue();if(assemblerIndex==0){RefreshAssemblers();RefreshInventories();BuildCargoMap();if(!inputsCleared){ClearAllAssemblerInputs();inputsCleared=true;}}if(assemblers.Count==0){Echo("No \""+assemblerTag+"\" assemblers");return;}var asm=assemblers[assemblerIndex];if(asm!=null&&asm.IsFunctional&&asm.Mode!=MyAssemblerMode.Disassembly){ClearAssemblerOutput(asm);ClearUnneededInput(asm);RestockAssembler(asm);ClearExcessIngots(asm);}assemblerIndex++;if(assemblerIndex>=assemblers.Count){assemblerIndex=0;fullCycles++;}Echo($"Asm {assemblerIndex+1}/{assemblers.Count} | Q:{transferQueue.Count}");}void RefreshAssemblers(){assemblers.Clear();GridTerminalSystem.GetBlocksOfType<IMyAssembler>(assemblers,a=>a.CustomName.Contains(assemblerTag));}void RefreshInventories(){cargoInventories.Clear();var b=new List<IMyTerminalBlock>();GridTerminalSystem.GetBlocksOfType(b);foreach(var bb in b)if(!assemblers.Contains(bb))for(int i=0;i<bb.InventoryCount;i++){var inv=bb.GetInventory(i);if(inv!=null)cargoInventories.Add(inv);} }void BuildCargoMap(){cargoMap.Clear();foreach(var inv in cargoInventories){sharedItemList.Clear();inv.GetItems(sharedItemList);foreach(var it in sharedItemList){var id=it.Type.TypeId+"/"+it.Type.SubtypeId;List<CargoItemRef> lst;if(!cargoMap.TryGetValue(id,out lst)){lst=new List<CargoItemRef>();cargoMap[id]=lst;}lst.Add(new CargoItemRef{inventory=inv,item=it});}}}void ClearAllAssemblerInputs(){foreach(var asm in assemblers)if(asm.Mode!=MyAssemblerMode.Disassembly){var inp=asm.InputInventory;sharedItemList.Clear();inp.GetItems(sharedItemList);foreach(var it in sharedItemList)EnqueueFromMap(it.Type.TypeId+"/"+it.Type.SubtypeId,(int)it.Amount,inp);} }void ClearAssemblerOutput(IMyAssembler asm){var o=asm.OutputInventory;sharedItemList.Clear();o.GetItems(sharedItemList);foreach(var it in sharedItemList)foreach(var d in cargoInventories)if(d.CanItemsBeAdded(it.Amount,it.Type)){QueueTransfer(o,d,it,(int)it.Amount);break;}}void ClearUnneededInput(IMyAssembler asm){var inp=asm.InputInventory;var q=new List<MyProductionItem>();asm.GetQueue(q);var allowed=new Dictionary<string,int>();foreach(var pi in q){int t=GetTier(pi.BlueprintId.SubtypeName);if(t>0){int need=prereqRatios[t]*bufferMultiplier;var id=techTypeIds[t-1];if(!allowed.ContainsKey(id)||need>allowed[id])allowed[id]=need;}}foreach(var id in ingotAndOreSet)allowed[id]=ingotTarget;sharedItemList.Clear();inp.GetItems(sharedItemList);var have=new Dictionary<string,int>();foreach(var it in sharedItemList){var id=it.Type.TypeId+"/"+it.Type.SubtypeId;have[id]=have.ContainsKey(id)?have[id]+(int)it.Amount:(int)it.Amount;}foreach(var it in sharedItemList){var id=it.Type.TypeId+"/"+it.Type.SubtypeId;int h=have.ContainsKey(id)?have[id]:0;int t=allowed.ContainsKey(id)?allowed[id]:0;if(h>t){int ex=h-t;foreach(var d in cargoInventories)if(d.CanItemsBeAdded(ex,it.Type)){QueueTransfer(inp,d,it,ex);break;}have[id]=t;}}}void RestockAssembler(IMyAssembler asm){var inp=asm.InputInventory;var q=new List<MyProductionItem>();asm.GetQueue(q);var allowed=new Dictionary<string,int>();foreach(var pi in q){int t=GetTier(pi.BlueprintId.SubtypeName);if(t>0){int need=prereqRatios[t]*bufferMultiplier;var id=techTypeIds[t-1];if(!allowed.ContainsKey(id)||need>allowed[id])allowed[id]=need;}}foreach(var kv in allowed){var id=kv.Key;int want=kv.Value;var p=id.Split('/');var type=new MyItemType(p[0],p[1]);int have=(int)inp.GetItemAmount(type);if(want>have)EnqueueFromMap(id,want-have,inp);}if(fullCycles%ingotRestockDelay==0)foreach(var id in ingotAndOreSet){var p=id.Split('/');var type=new MyItemType(p[0],p[1]);int have=(int)inp.GetItemAmount(type);if(ingotTarget>have)EnqueueFromMap(id,ingotTarget-have,inp);}}void ClearExcessIngots(IMyAssembler asm){var inp=asm.InputInventory;sharedItemList.Clear();inp.GetItems(sharedItemList);foreach(var it in sharedItemList){var id=it.Type.TypeId+"/"+it.Type.SubtypeId;if(!ingotAndOreSet.Contains(id))continue;int amt=(int)it.Amount;if(amt>ingotTarget){int ex=amt-ingotTarget;List<CargoItemRef> lst;if(cargoMap.TryGetValue(id,out lst))foreach(var r in lst)if(r.inventory.CanItemsBeAdded(ex,it.Type)){QueueTransfer(inp,r.inventory,it,ex);break;}}}}void EnqueueFromMap(string id,int need,IMyInventory dst){List<CargoItemRef> lst;if(!cargoMap.TryGetValue(id,out lst))return;foreach(var r in lst){if(need<=0)break;int a=(int)r.item.Amount;int x=Math.Min(a,need);if(x>0&&r.inventory.CanTransferItemTo(dst,r.item.Type)){QueueTransfer(r.inventory,dst,r.item,x);need-=x;}}}void QueueTransfer(IMyInventory s,IMyInventory d,MyInventoryItem it,int a){transferQueue.Add(new TransferJob{source=s,target=d,inventoryItem=it,amount=a});}void ProcessTransferQueue(){int c=Math.Min(transfersPerTick,transferQueue.Count);for(int i=0;i<c;i++){var j=transferQueue[0];transferQueue.RemoveAt(0);if(j.source.CanTransferItemTo(j.target,j.inventoryItem.Type)&&j.target.CanItemsBeAdded((MyFixedPoint)j.amount,j.inventoryItem.Type))j.source.TransferItemTo(j.target,j.inventoryItem,(MyFixedPoint)j.amount);}}int GetTier(string s){if(!s.StartsWith("Tech")||!s.EndsWith("x"))return-1;string num=s.Substring(4,s.Length-5);int v;if(!int.TryParse(num,out v))return-1;switch(v){case 2:return 0;case 4:return 1;case 8:return 2;case 16:return 3;case 32:return 4;}return-1;}class CargoItemRef{public IMyInventory inventory;public MyInventoryItem item;}class TransferJob{public IMyInventory source,target;public MyInventoryItem inventoryItem;public int amount;}
